package com.example.rokidgeminisecretary;
import android.app.*;import android.widget.*;import org.json.*;
final class ReferenceRefreshDialog {
 static void show(MainActivity owner,int index,long revision){new Thread(()->{try{JSONObject set=ReferenceRefresh.currentSet(owner,index,revision),comparison=ReferenceRefresh.compare(set,UnifiedRecords.catalog(owner));owner.runOnUiThread(()->render(owner,index,revision,comparison));}catch(Exception e){owner.runOnUiThread(()->Toast.makeText(owner,"比較できません："+e.getMessage(),1).show());}},"ReferenceSetCompare").start();}
 static void render(MainActivity owner,int index,long revision,JSONObject data){if(owner.isDestroyed())return;LinearLayout box=new LinearLayout(owner);box.setOrientation(1);TextView status=new TextView(owner);status.setText(data.optString("scope"));box.addView(status);java.util.ArrayList<CheckBox> checks=new java.util.ArrayList<>();java.util.ArrayList<JSONObject> choices=new java.util.ArrayList<>();JSONArray rows=data.optJSONArray("items");for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i),old=row.optJSONObject("old"),current=row.optJSONObject("current");TextView before=new TextView(owner);before.setText("保存済み："+old.optString("title")+"\n"+old.optString("body"));before.setTextIsSelectable(true);box.addView(before);String state=row.optString("state");if(state.equals("changed")){TextView after=new TextView(owner);String text=current.optString("body");after.setText("現在："+current.optString("title")+"\n"+text.substring(0,Math.min(2000,text.length()))+(text.length()>2000?"\n（2000文字を超えるため更新できません。短いメモとして保存し直してください）":""));after.setTextIsSelectable(true);box.addView(after);CheckBox selected=new CheckBox(owner);selected.setText("この項目を現在の内容へ更新する");selected.setChecked(false);selected.setEnabled(text.length()<=1200);box.addView(selected);checks.add(selected);choices.add(row);}else{TextView label=new TextView(owner);label.setText(state.equals("unchanged")?"元の記録と同じです":"元の記録を取得できません。保存済みのコピーは残します。");box.addView(label);}}
 Button save=new Button(owner);save.setText("選んだ項目だけ保存し直す");box.addView(save);ScrollView scroll=new ScrollView(owner);scroll.addView(box);AlertDialog dialog=new AlertDialog.Builder(owner).setTitle("参照セットの更新確認").setView(scroll).setPositiveButton("閉じる",null).create();save.setOnClickListener(v->{try{JSONArray selected=new JSONArray();for(int i=0;i<checks.size();i++)if(checks.get(i).isChecked())selected.put(new JSONObject().put("index",choices.get(i).getInt("index")).put("fingerprint",choices.get(i).getString("fingerprint")));if(selected.length()==0){status.setText("更新する項目を選んでください。保存内容は変更していません。");return;}save.setEnabled(false);new Thread(()->{try{ReferenceRefresh.update(owner,index,revision,selected,UnifiedRecords.catalog(owner));owner.runOnUiThread(()->{if(dialog.isShowing())status.setText("選んだ項目を保存し直しました。相談や送信はしていません。セットを開き直してください。");});}catch(Exception e){owner.runOnUiThread(()->{if(dialog.isShowing()){status.setText(e.getMessage());save.setEnabled(true);}});}},"ReferenceSetUpdate").start();}catch(Exception e){status.setText("選択内容を確認してください");}});dialog.show();}
 private ReferenceRefreshDialog(){}
}
